class ASMLicensedHttpClient(HttpClient):
    """ This class provides a client for the ASM Licensed API. """

    def __init__(self, base_url, connection_alias):
        super(ASMLicensedHttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/licensed/v1"

    def get_vnfcs_states(self, timeout=30):
        endpoint = '/vnfcs'
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def perform_commissioning(self, scf_file, should_activate, timeout=30):
        endpoint = f'/staged-plans/operations/{"provisions" if should_activate else "pre-activations"}'
        plan_name = path.splitext(path.split(scf_file)[1])[0]

        with open(scf_file, "rb") as file:
            multipart_data = MultipartEncoder(
                fields={"planFile": (plan_name, file, "text/xml"),
            })

            headers = {
                "Content-Type": multipart_data.content_type,
            }

            return self._send_post_request(endpoint=endpoint, data=str(multipart_data), timeout=timeout,
                                           headers=headers, log_payload=False)

