    def collect_l1_iq_data(self, sfn=65535, slot=0, capture_mode='ScheduleSynchronousStopOfOngoingContinuousCapture',
                           timeout=30):
        if slot != 0:
            raise IncorrectParameterValue("Parameter slot only accepts 0 as a value.")
        endpoint = '/traces/u-plane/l1-iq-capture/operations/collection'
        headers = {
            "Content-Type": "application/json",
        }
        data = {
            "sfn": sfn,
            "slot": slot,
            "captureMode": capture_mode
        }
        return self._send_post_request(endpoint=endpoint, headers=headers, json=data, timeout=timeout)

