    def activate_l1_iq_data_configuration(self, capture_on_event, capture_on_event_from_l1_hi_and_l1_low,
                                          dl_nr_subcell_list, ul_nr_subcell_list, ru_iq_data_parameters_list,
                                          capture_frame_offset, buffer_cycle, reason, timeout=30):
        endpoint = '/traces/u-plane/l1-iq-capture/operations/activation'
        headers = {
            "Content-Type": "application/json",
        }
        data = {
            "captureOnEvent": capture_on_event,
            "captureOnEventFromL1HiAndL1Low": capture_on_event_from_l1_hi_and_l1_low
        }
        optional_params = {
            "dlNrSubcellList": dl_nr_subcell_list,
            "ulNrSubcellList": ul_nr_subcell_list,
            "reason": reason
        }

        #those 3 params applies only when capture_on_event_from_l1_hi_and_l1_low=True
        if capture_on_event_from_l1_hi_and_l1_low:
            optional_params["bufferCycle"] = buffer_cycle
            optional_params["captureFrameOffset"] = capture_frame_offset
            optional_params["ruIqDataParametersList"] = ru_iq_data_parameters_list

        data.update({key: value for key, value in optional_params.items() if value is not None})
        return self._send_post_request(endpoint=endpoint, headers=headers, json=data, timeout=timeout)

